import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";var i=JSON.parse(`{"title":"Scrumban","description":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to flexibly and efficiently manage work.","frontmatter":{"title":"Scrumban","description":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to flexibly and efficiently manage work.","head":[["meta",{"name":"keywords","content":"Scrumban, Introduction to Scrumban, Scrumban Concept, What is Scrumban, Difference between Scrum and Kanban, Scrum vs Kanban, Agile Methodology, Agile Framework, Kanban Methodology, Scrum Methodology, Scrumban Process, Scrumban Operation Guide, Scrumban Board, WIP Limit, Workflow Management, How to use Kanban Board, Scrumban Advantages, Scrumban Features, Scrumban Effects, Scrumban Use Cases, Scrumban Adoption Effects, Scrumban Jira Setup, Scrumban Board Template, Scrumban Tools, Scrumban Collaboration Tools, Scrumban Workflow, Agile Project Management, Work Efficiency Methodology, Iterative Work Management, Bottleneck Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"Scrumban is a hybrid Agile methodology that combines Scrum's iterative structure with Kanban's flow management and WIP limits to flexibly and efficiently manage work."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/"}]],"sort":200},"headers":[],"relativePath":"en/agile/index.md","filePath":"en/agile/index.md","lastUpdated":1784425729000}`),a={name:`en/agile/index.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="scrumban" tabindex="-1">Scrumban <a class="header-anchor" href="#scrumban" aria-label="Permalink to “Scrumban”">​</a></h1><blockquote><p><strong>One-line summary:</strong> Scrumban is a process that combines the structure of Scrum (roles/meetings/backlog concepts) with Kanban&#39;s flow-centric approach and WIP (Work In Progress) limits. Instead of the strictness of a sprint, it emphasizes <strong>Flow</strong> and <strong>Pull</strong>, while maintaining Scrum-style ceremonies (planning/retrospectives) where necessary.</p></blockquote><h2 id="introduction-·-definition" tabindex="-1">Introduction · Definition <a class="header-anchor" href="#introduction-·-definition" aria-label="Permalink to “Introduction · Definition”">​</a></h2><p><strong>Scrumban</strong> is a hybrid process designed for software development and knowledge work teams to flexibly manage their workflow.</p><ul><li><strong>Scrum</strong>: Iterations (Sprints), fixed ceremonies (Sprint Planning/Review/Retro), clear roles</li><li><strong>Kanban</strong>: Visual board, WIP limits, pull-based work, continuous improvement Scrumban takes the advantages of both approaches and focuses on <strong>practical flow improvement</strong>.</li></ul><h2 id="when-is-it-good-to-use-scrumban" tabindex="-1">When is it good to use Scrumban? <a class="header-anchor" href="#when-is-it-good-to-use-scrumban" aria-label="Permalink to “When is it good to use Scrumban?”">​</a></h2><ul><li>Teams that are currently using <strong>Scrum</strong> but find it hard to bundle work into sprints due to frequent changes (urgent requests).</li><li>Teams managing flow with <strong>Kanban</strong>, but need disciplines like backlog management, prioritization, and regular retrospectives.</li><li>Maintenance, operations, and support teams (a mix of operational tasks + new feature development).</li><li>When <strong>continuous delivery</strong> and flow optimization are valued more than predictability.</li></ul><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core Concepts”">​</a></h2><ol><li><strong>Pull System</strong>: Work is only started (pulled into the next column) when the team has the capacity to handle it.</li><li><strong>WIP (Work In Progress) Limits</strong>: Limits the number of tasks in progress simultaneously to reduce multitasking and promote completion.</li><li><strong>Visualized Board</strong>: Clearly shows the status of work and instantly identifies bottlenecks.</li><li><strong>Regular Replenishment / Planning</strong>: Fills the backlog with tasks only when needed (periodically or upon reaching a threshold).</li><li><strong>Measurement and Improvement</strong>: Improves flow using metrics like cycle time, lead time, and throughput.</li><li><strong>Explicit Policies</strong>: Documents column transition conditions, prioritization rules, and Definition of Ready/Done.</li></ol><h2 id="scrum-vs-kanban-vs-scrumban" tabindex="-1">Scrum vs Kanban vs Scrumban <a class="header-anchor" href="#scrum-vs-kanban-vs-scrumban" aria-label="Permalink to “Scrum vs Kanban vs Scrumban”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Scrum</th><th>Kanban</th><th>Scrumban</th></tr></thead><tbody><tr><td>Iteration (Sprint)</td><td style="text-align:right;">Yes (Fixed length)</td><td>No (Continuous flow)</td><td>Optional / Mix of short iterations</td></tr><tr><td>WIP Limit</td><td style="text-align:right;">Implicit (Sprint scope)</td><td>Explicit</td><td>Explicit (Core)</td></tr><tr><td>Planning Method</td><td style="text-align:right;">Sprint Planning</td><td>Replenishment / Pull-based</td><td>Replenishment + Planning if needed</td></tr><tr><td>Roles</td><td style="text-align:right;">PO/SM/Dev</td><td>Flexible (No roles)</td><td>PO + Flow Manager (or maintain SM role)</td></tr><tr><td>Goal</td><td style="text-align:right;">Commitment (Sprint Goal)</td><td>Flow Optimization</td><td>Flow Optimization + Priority Management</td></tr></tbody></table><h2 id="roles-and-responsibilities" tabindex="-1">Roles and Responsibilities <a class="header-anchor" href="#roles-and-responsibilities" aria-label="Permalink to “Roles and Responsibilities”">​</a></h2><ul><li><strong>Product Owner (PO)</strong>: Backlog prioritization, stakeholder coordination, business value definition</li><li><strong>Flow Manager (or maintaining Scrum Master role)</strong>: Flow monitoring, bottleneck removal support, process improvement facilitation</li><li><strong>Team (Developers/Testers, etc.)</strong>: Complies with defined policies, starts/completes work using a pull method within WIP limits</li><li><strong>Stakeholders</strong>: Provide requirements/feedback, participate in reviews (if necessary)</li></ul><blockquote><p>Flexibly adjust roles according to the team&#39;s situation. The key is that the <strong>responsibility for flow management</strong> must be clear.</p></blockquote><h2 id="core-artifacts-·-tools" tabindex="-1">Core Artifacts · Tools <a class="header-anchor" href="#core-artifacts-·-tools" aria-label="Permalink to “Core Artifacts · Tools”">​</a></h2><ul><li><strong>Kanban Board</strong> (Physical or Digital) — including columns and WIP limits</li><li><strong>Backlog (Priority List)</strong> — candidates for pull-status tasks</li><li><strong>Explicit Policies</strong> — column transition rules, definitions (Ready/Done)</li><li><strong>Classes of Service</strong> — priority types such as Urgent/Fixed Date/Standard</li><li><strong>Metrics Dashboard</strong>: Cycle time, lead time, throughput, CFD (Cumulative Flow Diagram)</li></ul><h2 id="board-layout" tabindex="-1">Board Layout <a class="header-anchor" href="#board-layout" aria-label="Permalink to “Board Layout”">​</a></h2><p>Basic Scrumban Board (Example):</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th><th style="text-align:right;">Recommended WIP Limit</th></tr></thead><tbody><tr><td>Backlog</td><td>All prioritized tasks</td><td style="text-align:right;">—</td></tr><tr><td>Ready</td><td>Tasks ready to start (Can be moved to Do)</td><td style="text-align:right;">—</td></tr><tr><td>Doing / In Progress</td><td>Actually working</td><td style="text-align:right;">3</td></tr><tr><td>Code Review</td><td>Waiting for review</td><td style="text-align:right;">2</td></tr><tr><td>Testing</td><td>QA/Verification</td><td style="text-align:right;">2</td></tr><tr><td>Done</td><td>Completed</td><td style="text-align:right;">—</td></tr></tbody></table><p><strong>Simple ASCII Board:</strong></p><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Backlog -&gt; Ready -&gt; [Doing (WIP 3)] -&gt; Code Review (WIP 2) -&gt; Testing (WIP 2) -&gt; Done</span></span></code></pre></div><h2 id="workflow-rule-examples" tabindex="-1">Workflow Rule Examples <a class="header-anchor" href="#workflow-rule-examples" aria-label="Permalink to “Workflow Rule Examples”">​</a></h2><div class="language-text"><button title="Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Policy: Pull Condition (Move to Doing Column)</span></span>
<span class="line"><span>- Card is in the Ready column, and WIP in the Doing column &lt; WIP limit</span></span>
<span class="line"><span>- Meets the &#39;Definition of Ready&#39; for the task (Requirements/Test Cases/Design, etc.)</span></span>
<span class="line"><span>- Confirm availability of necessary resources (Tester/Reviewer)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Policy: Definition of Done (Completion Criteria)</span></span>
<span class="line"><span>- Code is merged and build is successful</span></span>
<span class="line"><span>- Passed automated/manual tests</span></span>
<span class="line"><span>- Deployment (or QA handover) documentation completed</span></span></code></pre></div><p><strong>Classes of Service Examples</strong></p><ul><li><strong>Expedite</strong>: Process immediately (Highest task priority, WIP exception allowed)</li><li><strong>Fixed Date</strong>: Needed by a specific date — requires schedule monitoring</li><li><strong>Standard</strong>: General request</li><li><strong>Intangible</strong>: Long-term value like technical debt</li></ul><h2 id="events-and-recommended-frequencies" tabindex="-1">Events and Recommended Frequencies <a class="header-anchor" href="#events-and-recommended-frequencies" aria-label="Permalink to “Events and Recommended Frequencies”">​</a></h2><ul><li><strong>Daily Stand-up (Daily, 10~15 mins)</strong>: Flow-centric (share bottlenecks/blockers rather than what you are doing)</li><li><strong>Replenishment / Backlog Refinement (Weekly or when needed)</strong>: Fill the Ready column — re-prioritize</li><li><strong>Planning (When needed)</strong>: Breakdown large tasks (Epics) or alternative planning — keep it short.</li><li><strong>Retrospective (Every 2~4 weeks)</strong>: Process improvement, review WIP limit adjustments</li><li><strong>Service Delivery Review / Ops Review (Monthly)</strong>: Review SLAs, SLEs, and metrics</li></ul><blockquote><p>You don&#39;t need to strictly schedule all meetings like in Scrum. Introduce meetings when you see <strong>points that disrupt the flow</strong>.</p></blockquote><h2 id="estimation-·-planning-methods" tabindex="-1">Estimation · Planning Methods <a class="header-anchor" href="#estimation-·-planning-methods" aria-label="Permalink to “Estimation · Planning Methods”">​</a></h2><ul><li><strong>Keep Story Points</strong>: Suitable for teams transitioning from Scrum. Good for predictability against throughput.</li><li><strong>No Estimates (Skip Estimation)</strong>: Predict using simple card counts + cycle time/throughput.</li><li><strong>Bucket (Time-based) Planning</strong>: Replenish based on the amount of work (throughput) that can be completed monthly.</li><li><strong>Recommendation</strong>: Reduce heavy estimation activities and predict using <strong>actual data (cycle time, throughput)</strong>.</li></ul><h2 id="core-metrics-definition-·-utilization" tabindex="-1">Core Metrics (Definition · Utilization) <a class="header-anchor" href="#core-metrics-definition-·-utilization" aria-label="Permalink to “Core Metrics (Definition · Utilization)”">​</a></h2><ul><li><strong>Lead Time</strong> = The point a card is backlogged (or created) → point of completion</li><li><strong>Cycle Time</strong> = Work start (Doing) → completion</li><li><strong>Throughput</strong> = Number of cards completed within a specific period</li><li><strong>WIP (Average number of tasks in progress)</strong></li><li><strong>Cumulative Flow Diagram (CFD)</strong>: Visualizes bottlenecks/flow changes with the cumulative area of each column</li><li><strong>Service Level Expectation (SLE)</strong>: e.g., 85% of tasks will be completed within 10 days</li></ul><p><strong>Reference Utilization</strong></p><ul><li>Little’s Law: <code>WIP = Throughput × Cycle Time</code> (using average values) — useful for predictions and identifying limits</li><li>Goal: Stabilize cycle time → increase predictability</li></ul><h2 id="from-scrum-to-scrumban" tabindex="-1">From Scrum to Scrumban <a class="header-anchor" href="#from-scrum-to-scrumban" aria-label="Permalink to “From Scrum to Scrumban”">​</a></h2><ol><li><strong>Map the current process</strong>: Visualize how work flows</li><li><strong>Configure the board</strong>: Start with minimal columns (Ready → Doing → QA → Done)</li><li><strong>Set WIP limits</strong>: Start conservatively (e.g., Doing = Number of team members ÷ 2)</li><li><strong>Determine replenishment rules</strong>: Decide when to fill Ready from Backlog (Weekly/Threshold)</li><li><strong>Collect data</strong>: Collect cycle time/throughput (2~4 weeks)</li><li><strong>Iterate adjustments</strong>: Adjust WIP/columns/policies in retrospectives</li></ol><h2 id="kanban-scrumban-adoption-checklist" tabindex="-1">Kanban/Scrumban Adoption Checklist <a class="header-anchor" href="#kanban-scrumban-adoption-checklist" aria-label="Permalink to “Kanban/Scrumban Adoption Checklist”">​</a></h2><ul><li>[ ] Does the board reflect the team&#39;s reality?</li><li>[ ] Are WIP limits set and understood by everyone?</li><li>[ ] Are Definition of Ready/Done documented?</li><li>[ ] Is the Replenishment frequency (or rule) set?</li><li>[ ] Does the Daily stand-up focus on bottlenecks?</li><li>[ ] Are cycle time, throughput, and CFD being collected and analyzed?</li><li>[ ] Are Classes of Service and policies defined?</li><li>[ ] Are process changes reflected in regular retros?</li></ul><h2 id="practical-tips-best-practices" tabindex="-1">Practical Tips &amp; Best Practices <a class="header-anchor" href="#practical-tips-best-practices" aria-label="Permalink to “Practical Tips &amp; Best Practices”">​</a></h2><ul><li><strong>Start small</strong>: Make the board and WIP limits small to get fast feedback.</li><li><strong>Stop starting — start finishing</strong>: A culture of finishing ongoing work rather than starting new ones.</li><li><strong>Team discipline upon WIP violation</strong>: Immediate discussion (why it was violated, identifying the bottleneck cause).</li><li><strong>Visual cues</strong>: Mark blockers/urgent cards with separate colors/stickers.</li><li><strong>Document policies</strong>: Clearly write down &quot;when to move a card&quot;.</li><li><strong>Automation</strong>: Shorten cycle time with CI/CD and automated tests.</li><li><strong>Data-driven decision making</strong>: Plan with actual cycle time/throughput rather than estimation.</li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to “Common Mistakes”">​</a></h2><ul><li>Setting WIP limits but not enforcing them</li><li>Maintaining Scrum ceremonies while ignoring WIP/Pull concepts</li><li>Creating classes and using them without criteria (priority confusion)</li><li>Making decisions based on &#39;feelings&#39; without collecting metrics</li><li>Overcomplicating the board with too many columns/segmentations</li></ul><h2 id="template-replenishment-meeting-simple-agenda" tabindex="-1">Template: Replenishment Meeting (Simple Agenda) <a class="header-anchor" href="#template-replenishment-meeting-simple-agenda" aria-label="Permalink to “Template: Replenishment Meeting (Simple Agenda)”">​</a></h2><ol><li>Completed work from the previous week (Brief review) — 5 mins</li><li>Check Ready column status (Re-prioritize) — 10~20 mins</li><li>Check current available resources against WIP limits — 5 mins</li><li>Decide on Pulling new tasks (Fill by priority) — 10~20 mins</li><li>Share Blockers / Risk factors — 5 mins</li></ol><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><p><strong>Q. Do sprints disappear completely?</strong> A. If the team wants, you can maintain short iterations (e.g., 2 weeks) while applying Scrumban principles. The key is flow improvement.</p><p><strong>Q. Should we keep using Story Points?</strong> A. Not necessarily. Predicting with throughput and cycle time is also widely used. Decide based on team culture and reporting needs.</p><p><strong>Q. How do we set WIP limits?</strong> A. Start conservatively (based on team size, or estimated from past throughput). Gradually adjust while keeping the limits.</p><h2 id="application-example" tabindex="-1">Application Example <a class="header-anchor" href="#application-example" aria-label="Permalink to “Application Example”">​</a></h2><ul><li>5 Team members → Doing WIP = 3 (Limit concurrent work)</li><li>Replenishment : Once a week (Monday)</li><li>Retrospective: Every 2 weeks (Mix of online/offline)</li><li>Metrics: Observe weekly throughput + 4-week cumulative cycle time</li></ul><h2 id="wrap-up-—-starter-guide" tabindex="-1">Wrap-up — Starter Guide <a class="header-anchor" href="#wrap-up-—-starter-guide" aria-label="Permalink to “Wrap-up — Starter Guide”">​</a></h2><ol><li><strong>Create the board</strong>,</li><li><strong>Set WIP limits</strong>,</li><li><strong>Document Pull rules and Definitions</strong>,</li><li><strong>Collect data (cycle time/throughput) for 2~4 weeks</strong> and <strong>adjust in retros</strong>.</li></ol>`,52)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};